def the_blemish_and_the_blood(case, data):
    """F7 — Deut 15:21-23 — THE CLASS visible and permanent: lame and blind the particulars that teach the class (126:1 — I8 in the Sifrei; Bekhorot 37a:16-19 I6 in the Bavli), the list by CALL to priesthood.acceptable's firstling table (Mishnah Bekhorot 6 whole); the testimony and the expert; the blemish after the slaughter; THE BLEMISHED EATEN IN THE GATES the unclean and the clean together (15:22 — 12:15 and 12:22's clause at its third seat by CALL to place_name); THE BLOOD (15:23 — 12:16's formula at its third seat by CALL to place_name and sanctions.blood — no new write); the pouring place; Leviticus 17:13's covering the contrast"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_blemish_class':
        ink('15:21', '"and if there be ANY BLEMISH in it, LAME OR BLIND, ANY ILL BLEMISH, you shall not sacrifice it to the LORD your God" — "lame or blind" %s (one seat; the priests\' "blind or lame" Leviticus 21:18 %s the order reversed), "any ill blemish" %s (one seat); 17:1\'s "any evil thing" the twin ahead — %d tokens in order; Malachi\'s "lame and sick" the run\'s %s; Leviticus 22:20 "all in which is a blemish" %s' % (P('פסח', 'או', 'עור'), P('עור', 'או', 'פסח'), P('כל', 'מום', 'רע'), TWIN['15:21 vs 17:1'], words('Mal', 1, 8)[:6], words('Lev', 22, 20)[:6]))
        move('the Sifrei 126:1 (read whole at the reading); 147:3-4 (reread whole — 17:1 by CALL when it comes); Bekhorot 37a:16-19, 37a:20-37b:5, 37b:7-8 (read whole at the docket); Mishnah Bekhorot 6:1-12 whole (read whole at the docket); cold_run_priesthood (CALL) — PR.acceptable(firstling_table) = %s, (beast_heads) = %s, (passing_blemish) = %s' % (V(PR_TABLE), V(PR_HEADS), V(PR_PASSING)), "LAME AND BLIND THE PARTICULARS THAT TEACH THE CLASS — 'any blemish' the general, 'lame or blind' the particulars, 'any ill blemish' the general again: what is like the particulars — EXPOSED AND NOT REGENERATING (126:1 — the Sifrei reads I8 in its own words: 'a particular singled out from the general to teach'; the Bavli reads I6 GENERAL-PARTICULAR-GENERAL at Bekhorot 37a:16-19, checked in MIDDOT.md — the hidden out by 'ill', the temporary out by reasoning and by the particulars' own choice 37a:20-37b:5; the measures 37b:7-8); THE LIST BY CALL to priesthood.acceptable's firstling table — 'one list serves the firstling (Deut 15:21 [IMPORT]) and Lev 27's redemption' (Mishnah Bekhorot 6:11-12's closing rule: slaughtered on the permanent blemishes, not on the passing, the old, the sick, the foul, the sinned-with, the killer, the doubtful sex); the six class heads of Leviticus 22:22 by CALL; the intended blemish barred (Mishnah 5:3): THE CELL'S VERDICT THE CLASS, never a list typed here")
        dat('THE PARAMETER the_blemish_class (by CALL — priesthood.acceptable(firstling_table); Mishnah Bekhorot 6 whole; 126:1 I8 / Bekhorot 37a I6 the two readings a DATA row); the exam\'s person the owner who slaughters the firstling on an exposed permanent blemish in his gates — accepted')
        return out("the blemish class (15:21) — 'any blemish, lame or blind, any ill blemish': exposed and not regenerating — the particulars teach the class (the Sifrei 126:1 I8; Bekhorot 37a:16-19 I6); the list by CALL to priesthood.acceptable's firstling table (Mishnah Bekhorot 6:11-12 — one list serves the firstling): THE PARAMETER the_blemish_class; the owner who slaughters the firstling on an exposed permanent blemish accepted", ['accepted'])
    if ask == 'the_passing_blemish':
        ink('15:21', '"any ILL blemish" — "ill" (רע) %s; 17:1\'s "any evil thing" %s' % ([x for x in W15(21) if x == 'רע'], words('Deut', 17, 1)[10:13]))
        move('Bekhorot 37a:20-37b:5 (read whole at the docket); Mishnah Bekhorot 6:12 (read whole at the docket); cold_run_priesthood (CALL) — PR.acceptable(firstling_table) not_on = %s, (passing_blemish) = %s' % (V(PR_TABLE).get('not_on'), V(PR_PASSING)), "THE PASSING BLEMISH OUT — the temporary out by reasoning and by the particulars' own choice (Bekhorot 37a:20-37b:5: the lame and the blind do not regenerate); Mishnah Bekhorot 6:12's closing rule: not slaughtered on the passing (the priests' table by CALL: 'the_passing_the_old_the_sick_the_foul_the_sinned_with_the_killer_the_doubtful_sex' not on); the passing blemish INCLUDED in Leviticus 22:20's bar from the altar (Sifra Emor 7 3 — the priesthood's cell) — barred from the altar AND from the slaughter in the gates: kept until permanent")
        dat('the passing blemish a DATA row (the_passing_blemish — Bekhorot 37a-37b; Mishnah 6:12; the priests\' table by CALL); the exam\'s person the one who slaughters the firstling on a passing blemish — barred from it')
        return out("the passing blemish (15:21) — the temporary out by reasoning and by the particulars' own choice (Bekhorot 37a:20-37b:5; Mishnah Bekhorot 6:12 — not slaughtered on the passing; priesthood.acceptable by CALL): the one who slaughters the firstling on a passing blemish barred from it", ['barred_from_it'])
    if ask == 'the_testimony_and_the_expert':
        ink('15:21', '"and if there be any blemish IN IT" — "in it" %s (15:22\'s "it" a limit, Yevamot 73b:15)' % ([x for x in W15(21) if x == 'בו'],))
        move('Bekhorot 35b:1-36b:15, 36b:16-37a:3, 37a:6-12 (read whole at the docket); Mishnah Bekhorot 4:4-5, 5:3 (read whole at the docket); cold_run_korach (CALL) — KO.the_gifts(blemish_expert) = %s, (suspect_firstborn) = %s' % (str(V(KO_EXPERT))[:90], str(V(KO_SUSPECT))[:60]), "THE TESTIMONY AND THE EXPERT — priests suspected, Israelites not (35b:1-36b:15: hearsay valid; the priest's own word; the ruling per R. Shimon ben Gamliel — the son and the daughter, not the wife); THE THREE LAYMEN where there is no expert (36b:16-37a:3); the unexamined sale's sanction (37a:6-12); the court's expert exempt, A NON-EXPERT PAYS a quarter of a small animal or half of a large (Mishnah Bekhorot 4:4 — korach's cell by CALL), a paid examiner disqualified unless like Ila (4:5); the intended blemish barred (5:3)")
        dat('the testimony and the expert a DATA row (the_testimony_and_the_expert — 35b-37a; Mishnah 4:4-5; korach by CALL); the exam\'s person the non-expert who permits the firstling on his own word — barred from it (he pays a quarter)')
        return out("the testimony and the expert (15:21) — priests suspected, Israelites not; the three laymen where there is no expert (Bekhorot 35b:1-37a:3); the non-expert who permits it pays a quarter of a small animal (Mishnah Bekhorot 4:4 — korach.the_gifts by CALL), the paid examiner disqualified (4:5): the non-expert who permits the firstling on his own word barred from it", ['barred_from_it'])
    if ask == 'the_blemish_after_the_slaughter':
        ink('15:21-22', '"you shall not sacrifice it … within your gates you shall eat it" — the slaughter\'s two verbs %s (15:21 "sacrifice", 15:22 "eat"); "sacrifice" in the book %s' % ([(v, x) for v in (21, 22) for x in W15(v) if x.startswith(('תזבח', 'תאכל'))], U('תזבח', 'תזבחנו', books=DT)))
        move('Mishnah Bekhorot 4:3-5 at 28a:12-28b:7, 28b:17 (read whole at the docket); Bekhorot 28a:13-28b:4 (read whole at the docket); cold_run_korach (CALL) — KO.the_gifts(blemish_expert) = %s' % (str(V(KO_EXPERT))[:110],), "THE BLEMISH SHOWN AFTER THE SLAUGHTER — one who slaughtered the firstling and then showed its blemish: R. Yehuda PERMITS, R. Meir FORBIDS AS A PENALTY (Mishnah Bekhorot 4:3 at 28a:12; korach's cell 'shown after slaughter — R. Yehuda / R. Meir'); the cornea's blemishes change after death, the body's not (28a:13-28b:4); the non-expert's payment (28b:6-7); the paid examiner not trusted unless an expert (28b:17)")
        dat('the blemish after the slaughter a DATA row (the_blemish_after_the_slaughter — Mishnah Bekhorot 4:3; 28a:12-28b:7 — two arms); the exam\'s person the one who slaughters the firstling and then finds a blemish of the body — barred from it on R. Meir\'s arm (the penalty), accepted on R. Yehuda\'s')
        return out("the blemish after the slaughter (15:21-22) — R. Yehuda permits, R. Meir forbids as a penalty (Mishnah Bekhorot 4:3 at 28a:12; the cornea's blemishes change after death, the body's not — 28a:13-28b:4; korach.the_gifts by CALL): the one who slaughters the firstling and then finds a blemish of the body barred from it on R. Meir's arm", ['barred_from_it'])
    if ask == 'the_blemished_in_the_gates':
        ink('15:22', '"WITHIN YOUR GATES you shall eat it, THE UNCLEAN AND THE CLEAN ALIKE, AS THE GAZELLE AND AS THE HART" — the verse %s; 12:15\'s "the unclean and the clean … as the gazelle and as the hart" %s, 12:22 "as the gazelle and the hart is eaten, so you shall eat it, the unclean and the clean alike" %s: THE CLAUSE\'S THREE SEATS %s; "within your gates you shall eat it" %s (one seat); "in your gates" in the chapter %s' % (W15(22), words('Deut', 12, 15)[-5:], words('Deut', 12, 22)[-6:], UNCLEAN_CLEAN, P('בשעריך', 'תאכלנו'), [v for v in range(1, 24) if 'בשעריך' in W15(v)]))
        move('the Sifrei 71:6-8 (reread whole — 12:15\'s rows citing 15:22); 126:2 (read whole at the reading); Bekhorot 33a:1-11 (credited by address); cold_run_place_name (CALL) — PN.the_profane_slaughter_the_blood_and_the_gates(the_unclean_and_the_clean) = %s, (the_eaters) = %s; PN.the_border_enlarged_and_the_altar(as_the_gazelle_and_the_hart) = %s' % (str(V(PN_UNCLEAN))[:60], str(V(PN_EATERS))[:50], str(V(PN_GAZELLE))[:60]), "THE BLEMISHED EATEN IN THE GATES, THE UNCLEAN AND THE CLEAN TOGETHER — 15:22 IS CHAPTER 12'S CLAUSE at its THIRD seat (12:15, 12:22, here — VERBATIM in the readback): 'the impure' unqualified, the impure and the pure eat from one dish (71:4-7 — the Sifrei's rows on 12:15 citing 15:22); 'as the gazelle and as the hart' the comparison's three seats (Bekhorot 33a:1-5 — Beit Shammai / Beit Hillel on the impure eater 33a:8-11); place_name's cells by CALL — the unclean and the clean, the eaters, the gazelle and the hart (the wild animal's slaughter, the hunted covered — the domestic not); the priest's household eats it, the blemished to any (Beit Hillel — korach by CALL at F6)")
        dat('the blemished in the gates a DATA row (the_blemished_in_the_gates — 15:22 the clause\'s third seat; place_name by CALL); the readback row 15:22 VERBATIM (profane_slaughter_permitted Deut 12:15 by kind); the exam\'s person the unclean who eats the blemished firstling with the clean in the gates — accepted')
        return out("the blemished in the gates (15:22) — 'within your gates you shall eat it, the unclean and the clean alike, as the gazelle and as the hart': chapter 12's clause at its third seat (12:15, 12:22 — place_name by CALL: the impure and the pure from one dish, the Sifrei 71:4-7; Bekhorot 33a:1-11): the unclean who eats the blemished firstling with the clean in the gates accepted", ['accepted'])
    if ask == 'the_permanent_blemish_lent':
        ink('15:22', '"within your gates you shall eat it" — "your gates" the book\'s sixteen seats %d; 12:15\'s "in all your gates" the blemished consecrated\'s release' % (len(U('בשעריך', books=DT)),))
        move('the Sifrei 71:6 (reread whole — I2 on "your gates" with 12:15); Bekhorot 15b:9-12 (credited from chapter 12\'s docket); cold_run_place_name (CALL) — PN.the_profane_slaughter_the_blood_and_the_gates(the_blemished_consecrated) = %s' % (str(V(PN_BLEMISHED))[:90],), "THE PERMANENT BLEMISH LENT TO ALL THE CONSECRATED — 'your gates' is said here of the firstling and 'your gates' at 12:15 of the blemished consecrated (71:6 — I2, checked in MIDDOT.md): as here a permanent blemish, so there — the redeemed consecrated slaughtered only on a permanent blemish; 12:15's release 'only the permission of consumption' (Bekhorot 15b:9-12 — place_name's cell on file by CALL: the consecration before the blemish, the firstborn and the gifts excluded by 'as the gazelle and the hart')")
        dat('the permanent blemish lent a DATA row (the_permanent_blemish_lent — 71:6 I2 "your gates"/"your gates"; place_name\'s the_blemished_consecrated by CALL); the exam\'s person the one who redeems the blemished consecrated and eats it in the gates — accepted')
        return out("the permanent blemish lent (15:22) — 'your gates' here and 'your gates' at 12:15: the blemished consecrated slaughtered only on a permanent blemish, as the firstling (the Sifrei 71:6 — I2; place_name.the_profane_slaughter_the_blood_and_the_gates by CALL — 'only the permission of consumption', Bekhorot 15b:9-12): the one who redeems the blemished consecrated and eats it in the gates accepted", ['accepted'])
    if ask == 'one_dish_and_the_heave_offering':
        ink('15:22', '"the unclean and the clean ALIKE" — "alike" (יחדו) %s at 12:22 and 15:22' % ([s for s in P('הטמא', 'והטהור', 'יחדו')],))
        move('the Sifrei 71:7-8 (reread whole); cold_run_place_name (CALL) — PN.the_profane_slaughter_the_blood_and_the_gates(the_eaters) = %s' % (str(V(PN_EATERS))[:70],), "ONE DISH AND THE HEAVE-OFFERING APART — 'the unclean and the clean alike': from one dish (71:7); might the heave-offering be eaten so? 'as the gazelle and as the hart' — not the heave-offering (71:8): A DATA ROW one_dish_and_the_heave_offering")
        dat('one dish and the heave-offering a DATA row (71:7-8); the exam\'s person the priest who eats the heave-offering from the impure\'s dish — barred from it')
        return out("one dish and the heave-offering (15:22) — the unclean and the clean from one dish, the heave-offering apart (the Sifrei 71:7-8; place_name by CALL): the priest who eats the heave-offering from the impure's dish barred from it", ['barred_from_it'])
    if ask == 'the_blood':
        ink('15:23', '"ONLY ITS BLOOD YOU SHALL NOT EAT; ON THE EARTH YOU SHALL POUR IT AS WATER" — the verse %s; 12:16 %s, 12:24 %s: the formula\'s THREE seats %s; "as water" in the Torah %s (Reuben\'s the fourth); "only" at 15:5 and 15:23; the shared run with 12:16 %d' % (W15(23), words('Deut', 12, 16), words('Deut', 12, 24), AS_WATER, U('כמים', books=T), TWIN['15:23 vs 12:16']))
        move('the Sifrei 126:2-4 (read whole at the reading); Keritot 20b-22a (credited from chapter 12\'s docket); cold_run_place_name (CALL) — PN.the_profane_slaughter_the_blood_and_the_gates(the_blood_like_water) = %s; PN.the_border_enlarged_and_the_altar(the_bloods_classes) = %s; cold_run_sanctions (CALL) — SA.blood(ban) = %s (fx %s), (lashes) = %s, (which_blood) = %s' % (str(V(PN_WATER))[:60], str(V(PN_CLASSES))[:60], V(SA_BAN), SA_BAN['fx'], V(SA_LASH), V(SA_WHICH)), "THE BLOOD — 12:16's formula at its THIRD seat (12:16, 12:24, here — VERBATIM in the readback: 'on the earth you shall pour it as water'): NO NEW WRITE — the ban 12:16's and Leviticus 17's by CALL (sanctions.blood: karet, lashed when warned — Makkot 3:2; the Sages lifeblood only against R. Yehuda any blood); the blood like water four ways (the Sifrei 71:14 — place_name's cell); the blood's classes (Keritot 20b-22a — the domestic, the wild, the bird; human blood outside the ban; the exudate's karet without atonement); DRINKING IS EATING (126:2); the olive a quantity (126:4 — REUSED, sanctions' olive)")
        dat('the blood NO NEW WRITE (12:16\'s formula by CALL to place_name and sanctions.blood — the ban Leviticus 17\'s); the readback row 15:23 VERBATIM (profane_slaughter_permitted Deut 12:15 by kind); the exam\'s person the one who eats the firstling\'s blood when warned — lashed (karet the ban)')
        return out("the blood (15:23) — 'only its blood you shall not eat; on the earth you shall pour it as water': 12:16's formula at its third seat, no new write (place_name.the_blood_like_water and sanctions.blood by CALL — karet the ban, lashed when warned; the Sages lifeblood only): the one who eats the firstling's blood when warned lashed", ['lashes'])
    if ask == 'the_witnesses_warning':
        ink('15:23', '"its blood you shall not eat" — the negation %s; the chapter\'s sixteen negations in thirteen verses' % ([x for x in W15(23) if x in NEG],))
        move('the Sifrei 126:3 (read whole at the reading); cold_run_sanctions (CALL) — SA.blood(lashes) = %s, SA.frame(court_warned) = %s, SA.blood(karet_own_eating) = %s' % (V(SA_LASH), V(SA_WARNED), V(SA_OWN)), "THE WITNESSES' WARNING GATING THE PENALTY — 'you shall not eat': the punishment written elsewhere, the warning here (126:3 — the prohibition the warning); sanctions' warning datum REUSED by CALL (lashed when warned — Makkot 3:2; karet rides only one's own eating)")
        dat('the witnesses\' warning a DATA row (the_witnesses_warning — 126:3; sanctions by CALL); the exam\'s person the one who eats the blood unwarned — exempt from lashes (karet by Heaven)')
        return out("the witnesses' warning (15:23) — the prohibition the warning, the punishment elsewhere (the Sifrei 126:3); lashed when warned (sanctions.blood by CALL — Makkot 3:2): the one who eats the blood unwarned exempt from lashes", ['exempt'])
    if ask == 'drinking_is_eating':
        ink('15:23', '"its blood you shall not EAT" — the eating verb %s; the chapter\'s "eat" tokens three %s' % ([x for x in W15(23) if x.startswith('תאכל')], [(v, x) for v in range(1, 24) for x in W15(v) if x.startswith(('תאכל', 'ואכל'))]))
        move('the Sifrei 126:2, 126:4 (read whole at the reading); cold_run_sanctions (CALL) — SA.blood(ban) = %s' % (V(SA_BAN),), "DRINKING IS EATING — 'you shall not eat': drinking included in eating (126:2); THE OLIVE a quantity (126:4 — the sanctions' olive REUSED by CALL: the ban's measure)")
        dat('drinking is eating a DATA row (drinking_is_eating — 126:2; the olive 126:4); the exam\'s person the one who drinks the blood — lashed (as the eater)')
        return out("drinking is eating (15:23) — drinking included in 'you shall not eat' (the Sifrei 126:2); the olive the quantity (126:4 — sanctions' measure by CALL): the one who drinks an olive's bulk of the blood lashed", ['lashes'])
    if ask == 'the_pouring_place':
        ink('15:23', '"ON THE EARTH you shall pour it as water" — "on the earth" %s' % ([x for x in W15(23) if x in ('על', 'הארץ')],))
        move('the Sifrei 126:5 (read whole at the reading); Mishnah Chullin 2:9 (read whole at the docket); cold_run_sanctions (CALL) — SA.covering(not_with_the_foot) = %s' % (V(SA_FOOT),), "THE POURING PLACE — 'on the earth': the ground, not the pit; the house, not the market — LEST HE IMITATE THE SECTARIANS (126:5; Mishnah Chullin 2:9: one may not slaughter into the sea or into a vessel, nor into a pit — the sectarians' way; a pit in the house permitted for the blood's flow): A DATA ROW the_pouring_place")
        dat('THE PARAMETER the_pouring_place (126:5; Mishnah Chullin 2:9 — the ground not the pit, the house not the market); the exam\'s person the one who pours the blood into a pit in the market — barred from it')
        return out("the pouring place (15:23) — 'on the earth': the ground not the pit, the house not the market, lest he imitate the sectarians (the Sifrei 126:5; Mishnah Chullin 2:9): THE PARAMETER the_pouring_place; the one who pours the blood into a pit in the market barred from it", ['barred_from_it'])
    if ask == 'the_covering_contrast':
        ink('15:23', '"on the earth you shall pour it AS WATER" — Leviticus 17:13\'s hunted blood "and he shall pour out its blood and COVER IT WITH DUST" %s: the contrast' % (words('Lev', 17, 13)[-5:],))
        move('the Sifrei 126:5-6 (read whole at the reading); cold_run_sanctions (CALL) — SA.covering(hunted_of_any_kind) = %s, (consecrated) = %s, (failed_slaughter) = %s; cold_run_place_name (CALL) — PN.the_border_enlarged_and_the_altar(as_the_gazelle_and_the_hart) = %s' % (V(SA_HUNTED), V(SA_CONSEC), V(SA_FAILED), str(V(PN_GAZELLE))[:50]), "THE COVERING'S CONTRAST — 'as water': no covering for the firstling's blood as for the hunted (Leviticus 17:13 by CALL to sanctions.covering — the hunted of any kind covered, the consecrated not, the failed slaughter exempt); 'as the gazelle and the hart' the comparison that teaches and is taught (75:15 — the wild animal's slaughter, the hunted covered, the domestic not: place_name by CALL); the neck and the seeds made susceptible (126:6 — a DATA row)")
        dat('the covering\'s contrast a DATA row (the_covering_contrast — Leviticus 17:13 by CALL; 126:5-6); the exam\'s person the hunter who covers the deer\'s blood and pours the firstling\'s as water — accepted')
        return out("the covering's contrast (15:23) — 'as water': no covering for the firstling's blood, the hunted covered with dust (Leviticus 17:13 by CALL to sanctions.covering — the consecrated no covering); 'as the gazelle and the hart' teaches and is taught (place_name by CALL); the seeds made susceptible (the Sifrei 126:6): the hunter who covers the deer's blood and pours the firstling's as water accepted", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_readback(case, data):
    """THE TABLE — the readback's forms on file, no new form: the rows one per verse, graded; the pointer row with its referent ahead; the state row; the two open rows; the twin diffed; the verses no one cites; no retrograde row"""
    del P_[:]
    ask = case['ask']
    rb_ = data['the_readback']['value']
    if ask == 'the_table':
        ink('15:1-23', 'the rows %d, one per verse %s; the grades %s' % (len(rb_), [r['verses'] for r in rb_] == ['Deut 15:%d' % v for v in range(1, 24)], dict(collections.Counter(r['grade'] for r in rb_))))
        move('THE LOOP.md step 6 (the forms on file — chapter 5\'s laws\' readback the form); every reference row\'s entry found on the tape by kind and first verse; every row\'s kin cell by CALL', 'THE READBACK ON THIS CHAPTER — law from its first word to its last with ONE narrative verb (15:15 a REFERENCE row on the tape\'s close, never a second act): T4 rows graded against the cells that compile their kin by CALL (twenty-three — every row has kin), T1 reference rows against the tape\'s lines by kind and first verse; the state row, the pointer row, the two open rows inside')
        dat('the table a DATA row (the_readback — the rows, the holes, the open rows); the exam\'s person the scholar who reads the table — accepted')
        return out("the table — twenty-three rows, one per verse: the grades %s; %d on the tape by kind and first verse, %d in the kin's cells by CALL, %d SUPPLIED (%d with their writes), the pointer row 15:6 (H), the state row 15:4, the open rows %s; no hole, no stretch, no retrograde row" % (dict(sorted(collections.Counter(r['grade'] for r in rb_).items())), sum(1 for r in rb_ if r['tape_kind']), sum(1 for r in rb_ if r['cell']), sum(1 for r in rb_ if r['grade'] == 'SUPPLIED'), sum(1 for r in rb_ if r['grade'] == 'SUPPLIED' and r['write']), data['the_readback']['open_rows']), ['accepted'])
    if ask == 'the_supplied_rows':
        ink('15:3-18', 'the SUPPLIED rows %s; the rows with writes %s' % ([r['verses'] for r in rb_ if r['grade'] == 'SUPPLIED'], [(r['verses'], r['write']) for r in rb_ if r['write']]))
        move('the design\'s readback paragraph (the forms on file)', 'THE SUPPLIED ROWS — the hand opened (15:7-11: no seat in Exodus, 22:24\'s loan the nearest by CALL), the gift (15:13-14: no seat in Exodus, the erection\'s price by CALL), the foreigner (15:3), the state row (15:4), the pointer row (15:6), the double hire (15:18) — the code\'s holes compiled at the chapter\'s own day with their writes')
        dat('the supplied rows a DATA row; the exam\'s person the scholar who reads the supplied rows — accepted')
        return out("the supplied rows — %s (%d), the rows with writes %s: the code's holes compiled at the chapter's own day" % ([r['verses'] for r in rb_ if r['grade'] == 'SUPPLIED'], sum(1 for r in rb_ if r['grade'] == 'SUPPLIED'), [(r['verses'], r['write']) for r in rb_ if r['write']]), ['accepted'])
    if ask == 'the_pointer_row':
        p = [r for r in rb_ if r['pointer']]
        ink('15:6', 'the pointer rows %s — the referent %s, the grade %s' % ([r['verses'] for r in p], p[0]['pointer'].get('referent') if p else None, p[0]['pointer'].get('grade') if p else None))
